// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
// Font Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type NewtonsCradleProps = Record<string, any>;

const NewtonsCradle: React.FC<NewtonsCradleProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 10,
  ballColor = "#e0e0e0",
  stringColor = "#555555",
  ballRadius = 40,
  stringLength = 300,
  cycleDuration = 1.5,
  separation = 0,
}) => {
  useFontLoader(["Inter"]);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Configuration
  const BALL_COUNT = 5;
  const MAX_ANGLE = 35 * (Math.PI / 180); // 35 degrees swing

  // Animation Timing
  const totalCycleFrames = cycleDuration * fps;
  const progress = (frame % totalCycleFrames) / totalCycleFrames; // 0 to 1

  // Easing functions for realistic physics (pendulum slows at top, speeds at bottom)
  // We use easeInCubic for falling (gravity) and easeOutCubic for rising
  const easeFall = Easing.in(Easing.cubic);
  const easeRise = Easing.out(Easing.cubic);

  const getBallRotation = (index: number) => {
    // Left Ball (Index 0)
    if (index === 0) {
      // 0.0 - 0.25: Falls from Left
      if (progress < 0.25) {
        return interpolate(progress, [0, 0.25], [MAX_ANGLE, 0], {
          easing: easeFall,
        });
      }
      // 0.25 - 0.75: Static at 0
      if (progress < 0.75) {
        return 0;
      }
      // 0.75 - 1.0: Rises to Left
      return interpolate(progress, [0.75, 1], [0, MAX_ANGLE], {
        easing: easeRise,
      });
    }

    // Right Ball (Index 4)
    if (index === BALL_COUNT - 1) {
      // 0.0 - 0.25: Static at 0
      if (progress < 0.25) {
        return 0;
      }
      // 0.25 - 0.50: Rises to Right (Negative angle)
      if (progress < 0.5) {
        return interpolate(progress, [0.25, 0.5], [0, -MAX_ANGLE], {
          easing: easeRise,
        });
      }
      // 0.50 - 0.75: Falls from Right
      if (progress < 0.75) {
        return interpolate(progress, [0.5, 0.75], [-MAX_ANGLE, 0], {
          easing: easeFall,
        });
      }
      // 0.75 - 1.0: Static at 0
      return 0;
    }

    // Middle balls (static with tiny impact jitter)
    // Optional: Add tiny jitter at impact points (0.25 and 0.75)
    // For sleekness, we keep them perfectly still as per ideal physics
    return 0;
  };

  const balls = Array.from({ length: BALL_COUNT }).map((_, i) => i);
  const totalWidth =
    BALL_COUNT * (ballRadius * 2) + (BALL_COUNT - 1) * separation;
  const startX = (width - totalWidth) / 2 + ballRadius;
  const pivotY = height / 2 - stringLength / 2 - ballRadius;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        <defs>
          <radialGradient id="ballGradient" cx="30%" cy="30%" r="70%">
            <stop offset="0%" stopColor="#ffffff" stopOpacity="0.9" />
            <stop offset="50%" stopColor={ballColor} />
            <stop offset="100%" stopColor="#000000" stopOpacity="0.6" />
          </radialGradient>
          <filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur in="SourceAlpha" stdDeviation="4" />
            <feOffset dx="2" dy="4" result="offsetblur" />
            <feComponentTransfer>
              <feFuncA type="linear" slope="0.3" />
            </feComponentTransfer>
            <feMerge>
              <feMergeNode />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* Top Bar (Implicit or minimal line) */}
        <line
          x1={startX - ballRadius * 2}
          y1={pivotY}
          x2={startX + totalWidth + ballRadius}
          y2={pivotY}
          stroke={stringColor}
          strokeWidth={4}
          strokeLinecap="round"
          opacity={0.8}
        />

        {balls.map((i) => {
          const x = startX + i * (ballRadius * 2 + separation);
          const rotation = getBallRotation(i);

          return (
            <g
              key={i}
              transform={`rotate(${
                (rotation * 180) / Math.PI
              }, ${x}, ${pivotY})`}
            >
              {/* String */}
              <line
                x1={x}
                y1={pivotY}
                x2={x}
                y2={pivotY + stringLength}
                stroke={stringColor}
                strokeWidth={2}
                opacity={0.6}
              />
              {/* Ball */}
              <circle
                cx={x}
                cy={pivotY + stringLength}
                r={ballRadius}
                fill="url(#ballGradient)"
                filter="url(#shadow)" // Remove if performance is bad, but looks sleek
              />
              {/* Shine/Reflection for extra sleekness */}
              <circle
                cx={x - ballRadius * 0.3}
                cy={pivotY + stringLength - ballRadius * 0.3}
                r={ballRadius * 0.25}
                fill="white"
                opacity={0.3}
                filter="blur(2px)"
              />
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default NewtonsCradle;